def ps(l,k):return(l**k*math.exp(-l))/math.factorial(k)
def club(s):
 s=s.lower()
 if "real" in s:return 2.1
 if "barca" in s or "barcel" in s or "city" in s or "bayern" in s:return 1.95
 if "psg" in s or "paris" in s or "liverpool" in s or "arsenal" in s:return 1.8
 if "aek" in s:return 1.15
 if "paok" in s or "olympi" in s:return 1.2
 return 1.3
